INSERT INTO feature VALUES('rap-frames','editor','Toolset callbacks as render-bus frames','rap-toolset','implemented','uncommon','mainstream editors','The toolset''s callbacks carry the render bus''s frames: `diagnostics` answers with a document''s diagnostic and goal cards and its version, with the lines `gandr view` prints as its `display_as`, and a subscription hears a `subscription_event` with the whole frame after each publication that changes it. Each callback carries an `Idempotency-Key`. Each delivery leaves on a thread of the toolset and is retried with a doubling wait after a `5xx` or a failed connection, never after another status, as the `[deliveries]` table configures; an answer stays in the store until a runtime takes it.','surface-agentic surface-lsp surface-tui surface-driver','crates/surface-agentic/src/rap.rs crates/surface-agentic/src/rap/deliver.rs crates/surface-driver/src/config.rs',NULL,'#6340');
